1	/**
2	 * Supabase-generated-style database types for CROBOT.
3	 *
4	 * These types mirror the SQL schema in supabase/migrations/ and are fully
5	 * compatible with the app-level types in src/types/index.ts.
6	 *
7	 * Usage:
8	 *   import { createClient } from '@supabase/supabase-js'
9	 *   import type { Database } from '@/types/database'
10	 *
11	 *   const supabase = createClient<Database>(url, key)
12	 *   const { data } = await supabase.from('scans').select('*')
13	 *   // data is typed as Tables<'scans'>[]
14	 */
15	
16	import type { CroPillar, PageType, PlanType, ScanStatus, Severity, Effort } from "./index";
17	
18	// ── Finding (JSONB shape stored inside scan_results.findings) ─
19	// Must stay in sync with the Finding interface in index.ts.
20	
21	export interface DbFinding {
22	  id: string;
23	  title: string;
24	  severity: Severity;
25	  current_state: string;
26	  recommendation: string;
27	  ai_suggestion: string;
28	  is_premium: boolean;
29	  effort: Effort;
30	  estimated_lift: string;
31	  category: string;
32	}
33	
34	// ── Table row shapes ──────────────────────────────────────────
35	
36	export interface ProfileRow {
37	  id: string;
38	  email: string;
39	  full_name: string;
40	  company_name: string | null;
41	  website_url: string | null;
42	  avatar_url: string | null;
43	  plan: PlanType;
44	  scans_used: number;
45	  scan_limit: number;
46	  stripe_customer_id: string | null;
47	  stripe_subscription_id: string | null;
48	  billing_cycle_end: string | null;
49	  created_at: string;
50	  updated_at: string;
51	}
52	
53	export interface ScanRow {
54	  id: string;
55	  user_id: string;
56	  url: string;
57	  favicon_url: string | null;
58	  page_title: string | null;
59	  page_type: PageType;
60	  status: ScanStatus;
61	  overall_score: number | null;
62	  issues_found: number;
63	  critical_issues: number;
64	  warnings: number;
65	  quick_wins: number;
66	  screenshot_url: string | null;
67	  device: "desktop" | "mobile" | "both";
68	  error_message: string | null;
69	  created_at: string;
70	  completed_at: string | null;
71	}
72	
73	export interface ScanResultRow {
74	  id: string;
75	  scan_id: string;
76	  pillar: CroPillar;
77	  score: number;
78	  weight: number;
79	  benchmark: number;
80	  findings: DbFinding[];
81	  created_at: string;
82	}
83	
84	export interface IntegrationRow {
85	  id: string;
86	  user_id: string;
87	  provider: "hotjar" | "google_analytics" | "clarity" | "search_console";
88	  access_token: string | null;
89	  refresh_token: string | null;
90	  is_active: boolean;
91	  connected_at: string;
92	}
93	
94	// ── Insert types (required fields only, omit auto-generated) ──
95	
96	export type ProfileInsert = Pick<ProfileRow, "id" | "email"> &
97	  Partial<
98	    Omit<ProfileRow, "id" | "email" | "created_at" | "updated_at">
99	  >;
100	
101	export type ScanInsert = Pick<ScanRow, "user_id" | "url"> &
102	  Partial<Omit<ScanRow, "user_id" | "url" | "id" | "created_at">>;
103	
104	export type ScanResultInsert = Pick<
105	  ScanResultRow,
106	  "scan_id" | "pillar" | "score" | "weight"
107	> &
108	  Partial<Omit<ScanResultRow, "scan_id" | "pillar" | "score" | "weight" | "id" | "created_at">>;
109	
110	export type IntegrationInsert = Pick<
111	  IntegrationRow,
112	  "user_id" | "provider"
113	> &
114	  Partial<Omit<IntegrationRow, "user_id" | "provider" | "id" | "connected_at">>;
115	
116	// ── Update types (all fields optional except primary key) ─────
117	
118	export type ProfileUpdate = Partial<
119	  Omit<ProfileRow, "id" | "created_at">
120	>;
121	
122	export type ScanUpdate = Partial<Omit<ScanRow, "id" | "user_id" | "created_at">>;
123	
124	export type ScanResultUpdate = Partial<
125	  Omit<ScanResultRow, "id" | "scan_id" | "pillar" | "created_at">
126	>;
127	
128	export type IntegrationUpdate = Partial<
129	  Omit<IntegrationRow, "id" | "user_id" | "provider" | "connected_at">
130	>;
131	
132	// ── Supabase Database generic type ────────────────────────────
133	
134	export interface Database {
135	  public: {
136	    Tables: {
137	      profiles: {
138	        Row: ProfileRow;
139	        Insert: ProfileInsert;
140	        Update: ProfileUpdate;
141	      };
142	      scans: {
143	        Row: ScanRow;
144	        Insert: ScanInsert;
145	        Update: ScanUpdate;
146	      };
147	      scan_results: {
148	        Row: ScanResultRow;
149	        Insert: ScanResultInsert;
150	        Update: ScanResultUpdate;
151	      };
152	      integrations: {
153	        Row: IntegrationRow;
154	        Insert: IntegrationInsert;
155	        Update: IntegrationUpdate;
156	      };
157	    };
158	    Views: Record<string, never>;
159	    Functions: {
160	      increment_scan_usage: {
161	        Args: { user_uuid: string };
162	        Returns: boolean;
163	      };
164	      reset_monthly_scans: {
165	        Args: Record<string, never>;
166	        Returns: void;
167	      };
168	    };
169	    Enums: Record<string, never>;
170	  };
171	}
172	
173	// ── Convenience helpers ───────────────────────────────────────
174	// Use these for typed Supabase client access.
175	
176	export type Tables<T extends keyof Database["public"]["Tables"]> =
177	  Database["public"]["Tables"][T]["Row"];
178	
179	export type TablesInsert<T extends keyof Database["public"]["Tables"]> =
180	  Database["public"]["Tables"][T]["Insert"];
181	
182	export type TablesUpdate<T extends keyof Database["public"]["Tables"]> =
183	  Database["public"]["Tables"][T]["Update"];
184	
185	export type DbFunctions = Database["public"]["Functions"];
