1	import { type LucideIcon } from "lucide-react";
2	import { Card, CardContent } from "@/components/ui/card";
3	import { useCountUp } from "@/hooks/use-count-up";
4	import { cn } from "@/lib/utils";
5	import { TrendingUp, TrendingDown } from "lucide-react";
6	
7	interface KpiCardProps {
8	  title: string;
9	  value: number;
10	  prefix?: string;
11	  suffix?: string;
12	  trend?: number; // percentage change, positive = good
13	  trendLabel?: string;
14	  icon: LucideIcon;
15	  iconColor?: string;
16	  iconBg?: string;
17	  valueColor?: string;
18	}
19	
20	export function KpiCard({
21	  title,
22	  value,
23	  prefix = "",
24	  suffix = "",
25	  trend,
26	  trendLabel = "vs last month",
27	  icon: Icon,
28	  iconColor = "text-primary",
29	  iconBg = "bg-primary/10",
30	  valueColor = "text-foreground",
31	}: KpiCardProps) {
32	  const animatedValue = useCountUp(value);
33	  const isPositiveTrend = trend !== undefined && trend > 0;
34	
35	  return (
36	    <Card className="border-slate-200 shadow-none hover:shadow-sm transition-shadow duration-200">
37	      <CardContent className="p-6">
38	        <div className="flex items-start justify-between">
39	          <div className="space-y-2">
40	            <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
41	              {title}
42	            </p>
43	            <p className={cn("text-[48px] font-bold leading-none tracking-tight", valueColor)}>
44	              {prefix}{animatedValue.toLocaleString()}{suffix}
45	            </p>
46	          </div>
47	          <div className={cn("flex h-10 w-10 items-center justify-center rounded-lg", iconBg)}>
48	            <Icon className={cn("h-5 w-5", iconColor)} />
49	          </div>
50	        </div>
51	        {trend !== undefined && (
52	          <div className="mt-3 flex items-center gap-1.5">
53	            {isPositiveTrend ? (
54	              <TrendingUp className="h-3.5 w-3.5 text-green-500" />
55	            ) : (
56	              <TrendingDown className="h-3.5 w-3.5 text-red-500" />
57	            )}
58	            <span
59	              className={cn(
60	                "text-xs font-medium",
61	                isPositiveTrend ? "text-green-600" : "text-red-600"
62	              )}
63	            >
64	              {isPositiveTrend ? "+" : ""}
65	              {trend}%
66	            </span>
67	            <span className="text-xs text-muted-foreground">{trendLabel}</span>
68	          </div>
69	        )}
70	      </CardContent>
71	    </Card>
72	  );
73	}
