-- ── Admin RBAC & Audit Logs ───────────────────────────────────
-- Migration: 004_admin_rbac
-- Adds: role column on profiles, is_admin() helper, admin RLS policies,
--       audit_logs table, is_banned column on profiles

-- ── Role column ───────────────────────────────────────────────

ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS role TEXT NOT NULL DEFAULT 'user'
  CHECK (role IN ('user', 'admin', 'super_admin'));

ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS is_banned BOOLEAN NOT NULL DEFAULT false;

CREATE INDEX IF NOT EXISTS idx_profiles_role ON public.profiles (role);

-- ── is_admin() helper ─────────────────────────────────────────
-- SECURITY DEFINER + STABLE so Postgres can inline it into RLS checks.

CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid()
      AND role IN ('admin', 'super_admin')
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE;

-- ── Admin-level RLS policies ──────────────────────────────────
-- These are ADDITIVE — existing per-user policies remain in place.
-- Postgres OR-combines all matching policies for the same operation.

CREATE POLICY "admin_profiles_select_all"
  ON public.profiles FOR SELECT
  USING (public.is_admin());

CREATE POLICY "admin_profiles_update_all"
  ON public.profiles FOR UPDATE
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles
      WHERE id = auth.uid()
        AND role = 'super_admin'
    )
  );

CREATE POLICY "admin_scans_select_all"
  ON public.scans FOR SELECT
  USING (public.is_admin());

CREATE POLICY "admin_scan_results_select_all"
  ON public.scan_results FOR SELECT
  USING (public.is_admin());

CREATE POLICY "admin_integrations_select_all"
  ON public.integrations FOR SELECT
  USING (public.is_admin());

-- ── Audit log table ───────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.audit_logs (
  id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  admin_id    UUID        NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  action      TEXT        NOT NULL,
  target_type TEXT,
  target_id   TEXT,
  metadata    JSONB       NOT NULL DEFAULT '{}'::jsonb,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_audit_logs_admin   ON public.audit_logs (admin_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_created ON public.audit_logs (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_logs_target  ON public.audit_logs (target_type, target_id);

ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;

CREATE POLICY "audit_logs_admin_read"
  ON public.audit_logs FOR SELECT
  USING (public.is_admin());

CREATE POLICY "audit_logs_admin_insert"
  ON public.audit_logs FOR INSERT
  WITH CHECK (public.is_admin());

