  icon: React.ElementType;
  disabled?: boolean;
  badge?: string;
}

const NAV_ITEMS: AdminNavItem[] = [
  { title: "Dashboard", href: "/admin", icon: LayoutDashboard },
  { title: "Users", href: "/admin/users", icon: Users },
  { title: "Scans", href: "/admin/scans", icon: ScanLine, disabled: true, badge: "Phase 5B" },
  { title: "Billing", href: "/admin/billing", icon: CreditCard, disabled: true, badge: "Phase 5B" },
  { title: "System", href: "/admin/system", icon: Activity, disabled: true, badge: "Phase 6B" },
  { title: "Feature Flags", href: "/admin/flags", icon: ToggleLeft, disabled: true, badge: "Phase 3B" },
  { title: "Support", href: "/admin/support", icon: MessageSquare, disabled: true, badge: "Phase 4B" },
  { title: "Audit Log", href: "/admin/audit-log", icon: ScrollText },
];

