                <span className="text-[13px] font-bold text-white tracking-tight">
                  CROBOT
                </span>
                <span className="text-[10px] text-white/40 font-medium uppercase tracking-wider">
                  Admin Panel
                </span>
              </div>
            </div>
          )}
          {collapsed && (
            <div className="flex h-7 w-7 items-center justify-center rounded-md bg-primary mx-auto">
              <Bot className="h-4 w-4 text-white" />
            </div>
          )}
        </div>

        {/* Nav */}
        <nav className="flex-1 px-2 py-3 space-y-0.5 overflow-y-auto">
          {NAV_ITEMS.map((item) => {
            const active = isActive(item.href);
            return (
              <div key={item.href}>
                {item.disabled ? (
                  <div
                    className={cn(
                      "flex items-center gap-2.5 rounded-md px-2.5 py-2 cursor-not-allowed opacity-40",
                      collapsed ? "justify-center" : ""
                    )}
                    title={item.disabled ? `Coming soon — ${item.badge}` : item.title}
                  >
                    <item.icon className="h-4 w-4 text-white/60 shrink-0" />
                    {!collapsed && (
                      <span className="text-[13px] text-white/60 flex-1 truncate">
                        {item.title}
                      </span>
                    )}
                    {!collapsed && item.badge && (
                      <Badge
                        variant="outline"
                        className="border-white/10 text-white/30 text-[9px] px-1 py-0 leading-tight"
                      >
                        {item.badge}
                      </Badge>
                    )}
                  </div>
                ) : (
                  <Link
                    to={item.href}
                    className={cn(
                      "flex items-center gap-2.5 rounded-md px-2.5 py-2 transition-colors",
                      collapsed ? "justify-center" : "",
                      active
                        ? "bg-primary/20 text-white border-l-2 border-primary rounded-none rounded-r-md"
                        : "text-white/60 hover:bg-white/5 hover:text-white"
                    )}
                    title={collapsed ? item.title : undefined}
                  >
                    <item.icon
                      className={cn(
                        "h-4 w-4 shrink-0",
                        active ? "text-primary" : "text-white/60"
                      )}
                    />
                    {!collapsed && (
                      <span
                        className={cn(
                          "text-[13px] truncate",
                          active ? "text-white font-medium" : "text-white/60"
                        )}
                      >
                        {item.title}
                      </span>
                    )}
                  </Link>
                )}
              </div>
            );
          })}

          <Separator className="my-2 bg-white/5" />

          <Link
            to="/dashboard"
            className={cn(
              "flex items-center gap-2.5 rounded-md px-2.5 py-2 text-white/50 hover:text-white hover:bg-white/5 transition-colors",
