import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";

export interface AdminStats {
  totalUsers: number;
  totalScans: number;
  activeUsers: number; // scanned in last 7 days
  failedScans: number;
}

async function fetchAdminStats(): Promise<AdminStats> {
  const sevenDaysAgo = new Date(
    Date.now() - 7 * 24 * 60 * 60 * 1000
  ).toISOString();

  const [
    { count: totalUsers, error: usersError },
    { count: totalScans, error: scansError },
    { count: failedScans, error: failedError },
    { data: activeData, error: activeError },
  ] = await Promise.all([
    supabase
      .from("profiles")
      .select("*", { count: "exact", head: true }),
    supabase
      .from("scans")
      .select("*", { count: "exact", head: true }),
    supabase
      .from("scans")
      .select("*", { count: "exact", head: true })
      .eq("status", "failed"),
    supabase
      .from("scans")
      .select("user_id")
      .gte("created_at", sevenDaysAgo),
  ]);

  if (usersError) throw new Error(usersError.message);
  if (scansError) throw new Error(scansError.message);
  if (failedError) throw new Error(failedError.message);
  if (activeError) throw new Error(activeError.message);

  const uniqueActiveUsers = new Set((activeData ?? []).map((r) => r.user_id))
    .size;

  return {
    totalUsers: totalUsers ?? 0,
    totalScans: totalScans ?? 0,
    activeUsers: uniqueActiveUsers,
    failedScans: failedScans ?? 0,
  };
}

export function useAdminStats() {
  return useQuery({
    queryKey: ["admin", "stats"],
    queryFn: fetchAdminStats,
    staleTime: 60_000, // 1 minute
  });
}

import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import type { ProfileRow } from "@/types/database";
import type { PlanType, UserRole } from "@/types/index";

export interface AdminUsersFilter {
  search?: string;
  plan?: PlanType | "";
  role?: UserRole | "";
}

export interface AdminUsersResult {
  users: ProfileRow[];
  total: number;
}

interface FetchAdminUsersParams {
  page: number;
  pageSize: number;
  filter: AdminUsersFilter;
  sortColumn: keyof ProfileRow;
  sortAsc: boolean;
}

const PAGE_SIZE = 20;

async function fetchAdminUsers({
  page,
  pageSize,
  filter,
  sortColumn,
  sortAsc,
}: FetchAdminUsersParams): Promise<AdminUsersResult> {
  let query = supabase
    .from("profiles")
    .select("*", { count: "exact" });

  if (filter.search) {
    // Use ilike for case-insensitive search across email and full_name
    query = query.or(
      `email.ilike.%${filter.search}%,full_name.ilike.%${filter.search}%`
    );
  }

  if (filter.plan) {
    query = query.eq("plan", filter.plan);
  }

  if (filter.role) {
    query = query.eq("role", filter.role);
  }

  const from = page * pageSize;
  const to = from + pageSize - 1;

  query = query
    .order(sortColumn as string, { ascending: sortAsc })
    .range(from, to);

  const { data, count, error } = await query;

  if (error) throw new Error(error.message);

  return {
    users: (data ?? []) as ProfileRow[],
    total: count ?? 0,
  };
}

export function useAdminUsers(params: {
  page?: number;
  pageSize?: number;
  filter?: AdminUsersFilter;
  sortColumn?: keyof ProfileRow;
  sortAsc?: boolean;
}) {
  const {
    page = 0,
    pageSize = PAGE_SIZE,
    filter = {},
    sortColumn = "created_at",
    sortAsc = false,
  } = params;

  return useQuery({
    queryKey: ["admin", "users", { page, pageSize, filter, sortColumn, sortAsc }],
    queryFn: () =>
      fetchAdminUsers({ page, pageSize, filter, sortColumn, sortAsc }),
    staleTime: 30_000,
    placeholderData: (prev) => prev,
  });
}

import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import type { AuditLogRow } from "@/types/database";

export interface AuditLogEntry extends AuditLogRow {
  admin_email?: string;
  admin_name?: string;
}

interface FetchAuditLogParams {
  page: number;
  pageSize: number;
  actionFilter?: string;
}

async function fetchAuditLog({
  page,
  pageSize,
  actionFilter,
}: FetchAuditLogParams): Promise<{ entries: AuditLogEntry[]; total: number }> {
  let query = supabase
    .from("audit_logs")
    .select(
      `
      *,
      profiles:admin_id (
        email,
        full_name
      )
    `,
      { count: "exact" }
    )
    .order("created_at", { ascending: false });

  if (actionFilter) {
    query = query.eq("action", actionFilter);
  }

  const from = page * pageSize;
  const to = from + pageSize - 1;
  query = query.range(from, to);

  const { data, count, error } = await query;

  if (error) throw new Error(error.message);

  const entries: AuditLogEntry[] = (data ?? []).map((row) => {
    // Supabase returns the joined profile as a nested object
    const profileData = row.profiles as
      | { email: string; full_name: string }
      | null;
    return {
      id: row.id,
      admin_id: row.admin_id,
      action: row.action,
      target_type: row.target_type,
      target_id: row.target_id,
      metadata: row.metadata as Record<string, unknown>,
      created_at: row.created_at,
      admin_email: profileData?.email,
      admin_name: profileData?.full_name,
    };
  });

  return { entries, total: count ?? 0 };
}

export function useAuditLog(params: {
  page?: number;
  pageSize?: number;
  actionFilter?: string;
}) {
  const { page = 0, pageSize = 25, actionFilter } = params;

  return useQuery({
    queryKey: ["admin", "audit-log", { page, pageSize, actionFilter }],
    queryFn: () => fetchAuditLog({ page, pageSize, actionFilter }),
    staleTime: 15_000,
    placeholderData: (prev) => prev,
  });
}

import { useMutation, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { PlanType, UserRole } from "@/types/index";
import { toast } from "sonner";

// ── Audit log helper ─────────────────────────────────────────

async function writeAuditLog(
  adminId: string,
  action: string,
  targetType: string,
  targetId: string,
  metadata: Record<string, unknown> = {}
) {
  const { error } = await supabase.from("audit_logs").insert({
    admin_id: adminId,
    action,
    target_type: targetType,
    target_id: targetId,
    metadata,
  });
  if (error) {
    // Audit log failures should not block the main action, but we still log them
    console.error("Audit log write failed:", error.message);
  }
}

// ── Change plan ───────────────────────────────────────────────

interface ChangePlanArgs {
  userId: string;
  plan: PlanType;
  previousPlan?: PlanType;
}

export function useChangePlan() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userId, plan, previousPlan }: ChangePlanArgs) => {
      if (!user) throw new Error("Not authenticated");

      const newLimit =
        plan === "agency" ? 500 : plan === "pro" ? 25 : 3;

      const { error } = await supabase
        .from("profiles")
        .update({ plan, scan_limit: newLimit })
        .eq("id", userId);

      if (error) throw new Error(error.message);

      await writeAuditLog(user.id, "change_plan", "profile", userId, {
        previous_plan: previousPlan,
        new_plan: plan,
      });
    },
    onSuccess: (_, { userId }) => {
      toast.success("Plan updated successfully");
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "user", userId] });
      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to update plan: ${error.message}`);
    },
  });
}

// ── Change role ───────────────────────────────────────────────

interface ChangeRoleArgs {
  userId: string;
  role: UserRole;
  previousRole?: UserRole;
}

export function useChangeRole() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userId, role, previousRole }: ChangeRoleArgs) => {
      if (!user) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("profiles")
        .update({ role })
        .eq("id", userId);

      if (error) throw new Error(error.message);

      await writeAuditLog(user.id, "change_role", "profile", userId, {
        previous_role: previousRole,
        new_role: role,
      });
    },
    onSuccess: (_, { userId }) => {
      toast.success("Role updated successfully");
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "user", userId] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to update role: ${error.message}`);
    },
  });
}

// ── Reset scan count ──────────────────────────────────────────

interface ResetScansArgs {
  userId: string;
  previousCount: number;
}

export function useResetScanCount() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userId, previousCount }: ResetScansArgs) => {
      if (!user) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("profiles")
        .update({ scans_used: 0 })
        .eq("id", userId);

      if (error) throw new Error(error.message);

      await writeAuditLog(user.id, "reset_scan_count", "profile", userId, {
        previous_scans_used: previousCount,
      });
    },
    onSuccess: (_, { userId }) => {
      toast.success("Scan count reset to 0");
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "user", userId] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to reset scan count: ${error.message}`);
    },
  });
}

// ── Ban / unban user ──────────────────────────────────────────

interface ToggleBanArgs {
  userId: string;
  ban: boolean;
}

export function useToggleBan() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userId, ban }: ToggleBanArgs) => {
      if (!user) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("profiles")
        .update({ is_banned: ban })
        .eq("id", userId);

      if (error) throw new Error(error.message);

      await writeAuditLog(user.id, ban ? "ban_user" : "unban_user", "profile", userId, {});
    },
    onSuccess: (_, { ban, userId }) => {
      toast.success(ban ? "User banned" : "User unbanned");
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "user", userId] });
      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to update ban status: ${error.message}`);
    },
  });
}

