import { Users, ScanLine, Activity, AlertTriangle, ScrollText, Clock } from "lucide-react";
import { KpiCard } from "@/components/shared/KpiCard";
import { PageHeader } from "@/components/shared/PageHeader";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { useAdminStats } from "@/hooks/admin/use-admin-stats";
import { useAuditLog } from "@/hooks/admin/use-audit-log";
import { formatDistanceToNow } from "date-fns";

function StatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
      {Array.from({ length: 4 }).map((_, i) => (
        <Skeleton key={i} className="h-[120px] rounded-xl" />
      ))}
    </div>
  );
}

function AuditFeedSkeleton() {
  return (
    <div className="space-y-3">
      {Array.from({ length: 5 }).map((_, i) => (
        <div key={i} className="flex items-start gap-3">
          <Skeleton className="h-7 w-7 rounded-full shrink-0" />
          <div className="flex-1 space-y-1.5">
            <Skeleton className="h-4 w-48" />
            <Skeleton className="h-3 w-32" />
          </div>
        </div>
      ))}
    </div>
  );
}

const ACTION_LABELS: Record<string, string> = {
  change_plan: "Changed plan",
  change_role: "Changed role",
  reset_scan_count: "Reset scan count",
  ban_user: "Banned user",
  unban_user: "Unbanned user",
};

const ACTION_COLORS: Record<string, string> = {
  change_plan: "bg-blue-100 text-blue-700",
  change_role: "bg-purple-100 text-purple-700",
  reset_scan_count: "bg-amber-100 text-amber-700",
  ban_user: "bg-red-100 text-red-700",
  unban_user: "bg-green-100 text-green-700",
};

export default function AdminDashboard() {
  const stats = useAdminStats();
  const auditLog = useAuditLog({ page: 0, pageSize: 10 });

  return (
    <div className="space-y-8">
      <PageHeader
        title="Admin Dashboard"
        description="Platform overview and recent admin activity."
      />

      {/* KPI row */}
      {stats.isLoading ? (
        <StatsSkeleton />
      ) : stats.isError ? (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700"
        >
          Failed to load stats. Check your admin permissions.
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
          <KpiCard
            title="Total Users"
            value={stats.data?.totalUsers ?? 0}
            icon={Users}
            iconColor="text-indigo-600"
            iconBg="bg-indigo-100"
          />
          <KpiCard
            title="Total Scans"
            value={stats.data?.totalScans ?? 0}
            icon={ScanLine}
            iconColor="text-sky-600"
            iconBg="bg-sky-100"
          />
          <KpiCard
            title="Active Users (7d)"
            value={stats.data?.activeUsers ?? 0}
            icon={Activity}
            iconColor="text-green-600"
            iconBg="bg-green-100"
          />
          <KpiCard
            title="Failed Scans"
            value={stats.data?.failedScans ?? 0}
            icon={AlertTriangle}
            iconColor="text-red-600"
            iconBg="bg-red-100"
          />
        </div>
      )}

      {/* Recent audit activity */}
      <Card className="border-slate-200 shadow-none">
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2">
            <ScrollText className="h-4 w-4 text-muted-foreground" />
            <CardTitle className="text-base font-semibold">Recent Admin Activity</CardTitle>
          </div>
        </CardHeader>
        <CardContent>
          {auditLog.isLoading ? (
            <AuditFeedSkeleton />
          ) : auditLog.isError ? (
            <p className="text-sm text-muted-foreground">
              No audit log entries yet.
            </p>
          ) : auditLog.data?.entries.length === 0 ? (
            <p className="py-8 text-center text-sm text-muted-foreground">
              No admin actions recorded yet.
            </p>
          ) : (
            <ul className="space-y-4" aria-label="Recent admin actions">
              {auditLog.data?.entries.map((entry) => (
                <li
                  key={entry.id}
                  className="flex items-start gap-3"
                >
                  <div className="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-slate-100">
                    <ScrollText className="h-3.5 w-3.5 text-slate-500" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="text-sm font-medium text-foreground">
                        {entry.admin_name ?? entry.admin_email ?? entry.admin_id}
                      </span>
                      <Badge
                        className={`text-[10px] px-1.5 py-0 font-medium border-0 ${
                          ACTION_COLORS[entry.action] ?? "bg-slate-100 text-slate-600"
                        }`}
                      >
                        {ACTION_LABELS[entry.action] ?? entry.action}
                      </Badge>
                    </div>
                    <div className="mt-0.5 flex items-center gap-1.5">
                      <Clock className="h-3 w-3 text-muted-foreground/60" />
                      <span className="text-xs text-muted-foreground">
                        {formatDistanceToNow(new Date(entry.created_at), {
                          addSuffix: true,
                        })}
                      </span>
                      {entry.target_id && (
                        <>
                          <span className="text-muted-foreground/40 text-xs">·</span>
                          <span className="font-mono text-xs text-muted-foreground/70">
                            {entry.target_id.slice(0, 8)}...
                          </span>
                        </>
                      )}
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Search,
  Users as UsersIcon,
  ChevronUp,
  ChevronDown,
  ChevronsUpDown,
  ChevronLeft,
  ChevronRight,
} from "lucide-react";
import { PageHeader } from "@/components/shared/PageHeader";
import { EmptyState } from "@/components/shared/EmptyState";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useAdminUsers, type AdminUsersFilter } from "@/hooks/admin/use-admin-users";
import type { ProfileRow } from "@/types/database";
import type { PlanType, UserRole } from "@/types/index";
import { format } from "date-fns";

const PLAN_BADGE_CLASSES: Record<PlanType, string> = {
  free: "bg-slate-100 text-slate-600 border-0",
  pro: "bg-indigo-100 text-indigo-700 border-0",
  agency: "bg-purple-100 text-purple-700 border-0",
};

const ROLE_BADGE_CLASSES: Record<UserRole, string> = {
  user: "bg-slate-100 text-slate-600 border-0",
  admin: "bg-amber-100 text-amber-700 border-0",
  super_admin: "bg-red-100 text-red-700 border-0",
};

type SortableColumn = "email" | "full_name" | "plan" | "scans_used" | "role" | "created_at";

function SortIcon({ column, sortColumn, sortAsc }: {
  column: SortableColumn;
  sortColumn: SortableColumn;
  sortAsc: boolean;
}) {
  if (sortColumn !== column) return <ChevronsUpDown className="ml-1 h-3.5 w-3.5 text-slate-300" />;
  return sortAsc
    ? <ChevronUp className="ml-1 h-3.5 w-3.5 text-primary" />
    : <ChevronDown className="ml-1 h-3.5 w-3.5 text-primary" />;
}

function TableSkeleton() {
  return (
    <>
      {Array.from({ length: 8 }).map((_, i) => (
        <TableRow key={i}>
          {Array.from({ length: 7 }).map((__, j) => (
            <TableCell key={j}>
              <Skeleton className="h-4 w-full max-w-[120px]" />
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  );
}

const PAGE_SIZE = 20;

export default function AdminUsers() {
  const navigate = useNavigate();
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [planFilter, setPlanFilter] = useState<PlanType | "">("");
  const [roleFilter, setRoleFilter] = useState<UserRole | "">("");
  const [page, setPage] = useState(0);
  const [sortColumn, setSortColumn] = useState<SortableColumn>("created_at");
  const [sortAsc, setSortAsc] = useState(false);

  // Simple debounce: update search on blur / Enter, or after typing stops
  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearch(e.target.value);
  };

  const handleSearchKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      setDebouncedSearch(search);
      setPage(0);
    }
  };

  const handleSearchBlur = () => {
    setDebouncedSearch(search);
    setPage(0);
  };

  const filter: AdminUsersFilter = {
    search: debouncedSearch || undefined,
    plan: planFilter || undefined,
    role: roleFilter || undefined,
  };

  const { data, isLoading, isError } = useAdminUsers({
    page,
    pageSize: PAGE_SIZE,
    filter,
    sortColumn: sortColumn as keyof ProfileRow,
    sortAsc,
  });

  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;

  const handleSort = (col: SortableColumn) => {
    if (sortColumn === col) {
      setSortAsc((asc) => !asc);
    } else {
      setSortColumn(col);
      setSortAsc(true);
    }
    setPage(0);
  };

  const SortableHeader = ({
    column,
    label,
  }: {
    column: SortableColumn;
    label: string;
  }) => (
    <TableHead
      className="cursor-pointer select-none whitespace-nowrap"
      onClick={() => handleSort(column)}
      aria-sort={
        sortColumn === column ? (sortAsc ? "ascending" : "descending") : "none"
      }
    >
      <span className="inline-flex items-center">
        {label}
        <SortIcon column={column} sortColumn={sortColumn} sortAsc={sortAsc} />
      </span>
    </TableHead>
  );

  return (
    <div className="space-y-6">
      <PageHeader
        title="Users"
        description={
          data ? `${data.total.toLocaleString()} total users` : "All registered users"
        }
      />

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-3">
        <div className="relative flex-1 min-w-[200px] max-w-xs">
          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Search by email or name..."
            value={search}
            onChange={handleSearchChange}
            onKeyDown={handleSearchKeyDown}
            onBlur={handleSearchBlur}
            className="pl-9"
            aria-label="Search users"
          />
        </div>

        <Select
          value={planFilter}
          onValueChange={(v) => {
            setPlanFilter(v as PlanType | "");
            setPage(0);
          }}
        >
          <SelectTrigger className="w-[130px]" aria-label="Filter by plan">
            <SelectValue placeholder="All plans" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="">All plans</SelectItem>
            <SelectItem value="free">Free</SelectItem>
            <SelectItem value="pro">Pro</SelectItem>
            <SelectItem value="agency">Agency</SelectItem>
          </SelectContent>
        </Select>

        <Select
          value={roleFilter}
          onValueChange={(v) => {
            setRoleFilter(v as UserRole | "");
            setPage(0);
          }}
        >
          <SelectTrigger className="w-[150px]" aria-label="Filter by role">
            <SelectValue placeholder="All roles" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="">All roles</SelectItem>
            <SelectItem value="user">User</SelectItem>
            <SelectItem value="admin">Admin</SelectItem>
            <SelectItem value="super_admin">Super Admin</SelectItem>
          </SelectContent>
        </Select>

        {(debouncedSearch || planFilter || roleFilter) && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              setSearch("");
              setDebouncedSearch("");
              setPlanFilter("");
              setRoleFilter("");
              setPage(0);
            }}
          >
            Clear filters
          </Button>
        )}
      </div>

      {/* Table */}
      <div className="rounded-xl border border-slate-200 overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow className="bg-slate-50 hover:bg-slate-50">
              <SortableHeader column="email" label="Email" />
              <SortableHeader column="full_name" label="Name" />
              <SortableHeader column="plan" label="Plan" />
              <SortableHeader column="scans_used" label="Scans Used" />
              <SortableHeader column="role" label="Role" />
              <SortableHeader column="created_at" label="Signed Up" />
              <TableHead className="w-10" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableSkeleton />
            ) : isError ? (
              <TableRow>
                <TableCell
                  colSpan={7}
                  className="py-10 text-center text-sm text-red-600"
                >
                  Failed to load users. Check your admin permissions.
                </TableCell>
              </TableRow>
            ) : data?.users.length === 0 ? (
              <TableRow>
                <TableCell colSpan={7} className="p-0">
                  <EmptyState
                    icon={UsersIcon}
                    title="No users found"
                    description="Try adjusting your search or filters."
                  />
                </TableCell>
              </TableRow>
            ) : (
              data?.users.map((user) => (
                <TableRow
                  key={user.id}
                  className="cursor-pointer hover:bg-slate-50 transition-colors"
                  onClick={() => navigate(`/admin/users/${user.id}`)}
                  aria-label={`View user ${user.email}`}
                >
                  <TableCell className="font-mono text-xs text-muted-foreground">
                    {user.email}
                  </TableCell>
                  <TableCell className="text-sm font-medium">
                    <div className="flex items-center gap-1.5">
                      {user.full_name || (
                        <span className="text-muted-foreground/50">—</span>
                      )}
                      {user.is_banned && (
                        <Badge className="bg-red-100 text-red-700 border-0 text-[10px] px-1.5 py-0">
                          Banned
                        </Badge>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <Badge
                      className={`text-[11px] px-2 py-0.5 capitalize ${
                        PLAN_BADGE_CLASSES[user.plan]
                      }`}
                    >
                      {user.plan}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-sm text-muted-foreground">
                    {user.scans_used} / {user.scan_limit}
                  </TableCell>
                  <TableCell>
                    <Badge
                      className={`text-[11px] px-2 py-0.5 capitalize ${
                        ROLE_BADGE_CLASSES[user.role]
                      }`}
                    >
                      {user.role.replace("_", " ")}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-sm text-muted-foreground">
                    {format(new Date(user.created_at), "MMM d, yyyy")}
                  </TableCell>
                  <TableCell>
                    <ChevronRight className="h-4 w-4 text-slate-300" />
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">
            Page {page + 1} of {totalPages} ({data?.total.toLocaleString()} users)
          </p>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={page === 0}
              aria-label="Previous page"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
              disabled={page >= totalPages - 1}
              aria-label="Next page"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import type { ProfileRow } from "@/types/database";
import type { ScanRow } from "@/types/database";

interface UserDetailResult {
  profile: ProfileRow;
  scans: ScanRow[];
  totalScans: number;
}

async function fetchUserDetail(userId: string): Promise<UserDetailResult> {
  const [profileResult, scansResult] = await Promise.all([
    supabase
      .from("profiles")
      .select("*")
      .eq("id", userId)
      .single(),
    supabase
      .from("scans")
      .select("*", { count: "exact" })
      .eq("user_id", userId)
      .order("created_at", { ascending: false })
      .limit(20),
  ]);

  if (profileResult.error) throw new Error(profileResult.error.message);
  if (scansResult.error) throw new Error(scansResult.error.message);

  return {
    profile: profileResult.data as ProfileRow,
    scans: (scansResult.data ?? []) as ScanRow[],
    totalScans: scansResult.count ?? 0,
  };
}

export function useAdminUserDetail(userId: string) {
  return useQuery({
    queryKey: ["admin", "user", userId],
    queryFn: () => fetchUserDetail(userId),
    enabled: Boolean(userId),
    staleTime: 30_000,
  });
}

