export default function AuditLog() {
  const [page, setPage] = useState(0);
  const [actionFilter, setActionFilter] = useState("");

  const { data, isLoading, isError } = useAuditLog({
    page,
    pageSize: PAGE_SIZE,
    actionFilter: actionFilter || undefined,
  });

  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Audit Log"
        description="Chronological record of all admin actions."
      />

      {/* Filter */}
      <div className="flex items-center gap-3">
        <Filter className="h-4 w-4 text-muted-foreground" />
        <Select
          value={actionFilter}
          onValueChange={(v) => {
            setActionFilter(v);
            setPage(0);
          }}
        >
          <SelectTrigger className="w-[180px]" aria-label="Filter by action type">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {ACTION_OPTIONS.map((opt) => (
              <SelectItem key={opt.value} value={opt.value}>
                {opt.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {actionFilter && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              setActionFilter("");
              setPage(0);
            }}
          >
            Clear filter
          </Button>
        )}
        {data && (
          <span className="ml-auto text-sm text-muted-foreground">
            {data.total.toLocaleString()} entries
          </span>
        )}
      </div>

      {/* Entries */}
      {isLoading ? (
        <LogSkeleton />
      ) : isError ? (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 p-6 text-center text-sm text-red-700"
        >
          Failed to load audit log. Check your admin permissions.
        </div>
      ) : data?.entries.length === 0 ? (
        <EmptyState
          icon={ScrollText}
          title="No audit log entries"
          description={
            actionFilter
              ? "No entries match the selected action filter."
              : "Admin actions will appear here once they occur."
          }
        />
      ) : (
        <ol className="space-y-2.5" aria-label="Audit log entries">
          {data?.entries.map((entry) => {
            const metadata = entry.metadata as Record<string, string>;
            const metaKeys = Object.keys(metadata).filter(
              (k) => metadata[k] !== undefined && metadata[k] !== null
            );

            return (
              <li key={entry.id}>
                <Card className="border-slate-200 shadow-none hover:border-slate-300 transition-colors">
                  <CardContent className="flex items-start gap-4 p-4">
                    {/* Icon */}
                    <div className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-slate-100">
                      <ScrollText className="h-4 w-4 text-slate-500" />
                    </div>

                    {/* Content */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="text-sm font-medium text-foreground">
                          {entry.admin_name ?? entry.admin_email ?? entry.admin_id}
                        </span>
                        <Badge
                          className={`text-[10px] px-1.5 py-0 ${
                            ACTION_BADGE_CLASSES[entry.action] ??
                            "bg-slate-100 text-slate-600 border-0"
                          }`}
                        >
                          {ACTION_LABELS[entry.action] ?? entry.action}
                        </Badge>
                      </div>

                      {/* Target */}
                      {entry.target_id && (
                        <p className="mt-0.5 font-mono text-[11px] text-muted-foreground/70">
                          Target: {entry.target_type} · {entry.target_id}
                        </p>
                      )}

                      {/* Metadata pills */}
                      {metaKeys.length > 0 && (
                        <div className="mt-1.5 flex flex-wrap gap-1">
                          {metaKeys.map((k) => (
                            <MetadataPill
                              key={k}
                              label={k.replace(/_/g, " ")}
                              value={String(metadata[k])}
                            />
                          ))}
                        </div>
                      )}
                    </div>

                    {/* Timestamp */}
                    <div className="shrink-0 text-right">
                      <div className="flex items-center gap-1 text-xs text-muted-foreground justify-end">
                        <Clock className="h-3 w-3" />
                        <span title={format(new Date(entry.created_at), "PPpp")}>
                          {formatDistanceToNow(new Date(entry.created_at), {
                            addSuffix: true,
