import { lazy, Suspense } from "react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { BrowserRouter, Route, Routes } from "react-router-dom";
import { Toaster as Sonner } from "@/components/ui/sonner";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import { AuthProvider } from "@/contexts/AuthContext";
import { ProtectedRoute } from "@/components/ProtectedRoute";
import { AdminRoute } from "@/components/AdminRoute";
import { AppLayout } from "@/components/AppLayout";
import Dashboard from "@/pages/Dashboard";
import Scan from "@/pages/Scan";
import Reports from "@/pages/Reports";
import AuditReport from "@/pages/AuditReport";
import Integrations from "@/pages/Integrations";
import SettingsPage from "@/pages/Settings";
import Pricing from "@/pages/Pricing";
import Landing from "@/pages/Landing";
import Login from "@/pages/Login";
import Signup from "@/pages/Signup";
import AuthCallback from "@/pages/AuthCallback";
import ForgotPassword from "@/pages/ForgotPassword";
import ResetPassword from "@/pages/ResetPassword";
import AgentHub from "@/pages/AgentHub";
import AgentWorkspace from "@/pages/AgentWorkspace";
import NotFound from "@/pages/NotFound";

// ── Admin routes (lazy loaded) ────────────────────────────────
const AdminLayout = lazy(() =>
  import("@/components/AdminLayout").then((m) => ({ default: m.AdminLayout }))
);
const AdminDashboard = lazy(() => import("@/pages/admin/AdminDashboard"));
const AdminUsers = lazy(() => import("@/pages/admin/Users"));
const AdminUserDetail = lazy(() => import("@/pages/admin/UserDetail"));
const AdminAuditLog = lazy(() => import("@/pages/admin/AuditLog"));

function AdminLoadingSpinner() {
  return (
    <div className="flex min-h-screen items-center justify-center bg-background">
      <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
    </div>
  );
}

const queryClient = new QueryClient();

const App = () => (
  <QueryClientProvider client={queryClient}>
    <TooltipProvider>
      <Toaster />
      <Sonner />
      <BrowserRouter>
        <AuthProvider>
          <Routes>
            {/* Public routes */}
            <Route path="/" element={<Landing />} />
            <Route path="/login" element={<Login />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/auth/callback" element={<AuthCallback />} />
            <Route path="/forgot-password" element={<ForgotPassword />} />
            <Route path="/reset-password" element={<ResetPassword />} />

            {/* Protected app routes */}
            <Route element={<ProtectedRoute />}>
              <Route element={<AppLayout />}>
                <Route path="/dashboard" element={<Dashboard />} />
                <Route path="/scan" element={<Scan />} />
                <Route path="/reports" element={<Reports />} />
                <Route path="/reports/:id" element={<AuditReport />} />
                <Route path="/agents" element={<AgentHub />} />
                <Route path="/agents/:taskId" element={<AgentWorkspace />} />
                <Route path="/integrations" element={<Integrations />} />
                <Route path="/settings" element={<SettingsPage />} />
                <Route path="/pricing" element={<Pricing />} />
              </Route>

              {/* Admin routes — nested inside ProtectedRoute, guarded by AdminRoute */}
              <Route element={<AdminRoute />}>
                <Route
                  path="/admin"
                  element={
                    <Suspense fallback={<AdminLoadingSpinner />}>
                      <AdminLayout />
                    </Suspense>
                  }
                >
                  <Route
                    index
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminDashboard />
                      </Suspense>
                    }
                  />
                  <Route
                    path="users"
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminUsers />
                      </Suspense>
                    }
                  />
                  <Route
                    path="users/:userId"
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminUserDetail />
                      </Suspense>
                    }
                  />
                  <Route
                    path="audit-log"
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminAuditLog />
                      </Suspense>
                    }
                  />
                </Route>
              </Route>
            </Route>

            <Route path="*" element={<NotFound />} />
          </Routes>
        </AuthProvider>
      </BrowserRouter>
    </TooltipProvider>
  </QueryClientProvider>
);

export default App;
